"""L10M-ORACLE-3 stable closed-loop navigation policy."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, confidence hysteresis, and bounded target tracking.

    The controller verifies fresh tracks, pauses briefly after loss, then scans
    in a persistent direction.  When locked, it steers toward the target with
    a small deadband and uses corridor availability as a safe fallback.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")
    last_bearing = float(memory.get("last_bearing", 0.0))
    scan_phase = int(memory.get("scan_phase", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def finish(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return finish("STOP", 0.99, "STOPPED")

    confident = visible and target_confidence >= 0.55 and identity_confidence >= 0.60
    if not confident:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            memory["state"] = "REACQUIRE"
            if lost_steps <= 1:
                return finish("STOP", 0.92, "REACQUIRE")

        # Keep a scan direction for several frames to avoid rapid oscillation.
        scan_phase += 1
        if scan_phase >= 3:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            scan_phase = 0
        memory["scan_direction"] = scan_direction
        memory["scan_phase"] = scan_phase
        return finish(scan_direction, 0.74, "SEARCH")

    memory["last_bearing"] = max(-180.0, min(180.0, bearing))
    memory["scan_phase"] = 0

    # Require a short confirmation unless an already locked, strong track exists.
    if track_age < 2 and not (
        state in {"LOCKED", "APPROACH"} and target_confidence >= 0.75
    ):
        return finish("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near" and heading_error <= 15.0 and identity_confidence >= 0.80:
        return finish("ARRIVED", 0.96, "ARRIVED")

    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    # Hysteresis prevents needless left/right flips near the centerline.
    deadband = 6.0 if last_action in {"VEER_LEFT", "VEER_RIGHT"} else 12.0
    desired = ""
    if bearing < -deadband and left:
        desired = "VEER_LEFT"
    elif bearing > deadband and right:
        desired = "VEER_RIGHT"
    elif center:
        desired = "FORWARD"
    elif bearing < 0.0 and left:
        desired = "VEER_LEFT"
    elif bearing > 0.0 and right:
        desired = "VEER_RIGHT"
    elif left:
        desired = "VEER_LEFT"
    elif right:
        desired = "VEER_RIGHT"

    if desired:
        confidence = 0.90 if desired in {"FORWARD", "VEER_LEFT", "VEER_RIGHT"} else 0.82
        return finish(desired, confidence, "APPROACH")

    return finish("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
